private fun DrawScope.drawIcon(
    d: String,
    color: Color,
    turn: Float = 0f,
) {
    val path = PathParser().parsePathString(d).toPath()
    val k = size.minDimension / 24f
    rotate(turn, Offset(size.width / 2, size.height / 2)) {
        withTransform({ scale(k, k, Offset.Zero) }) { drawPath(path, color) }
    }
}

/** Handset. [hangUp] turns it down, like the iPhone's red button. */
@Composable
fun PhoneGlyph(
    tint: Color,
    size: Dp = 18.dp,
    hangUp: Boolean = false,
) {
    Canvas(Modifier.size(size)) { drawIcon(PHONE, tint, if (hangUp) 135f else 0f) }
}

@Composable
fun BoltGlyph(
    tint: Color,
    size: Dp = 18.dp,
) {
    Canvas(Modifier.size(size)) { drawIcon(BOLT, tint) }
}

@Composable
fun ArrowUpGlyph(
    tint: Color,
    size: Dp = 22.dp,
) {
    Canvas(Modifier.size(size)) { drawIcon(ARROW_UP, tint) }
}

/** Any Material 24x24 path as an icon. */
@Composable
fun Glyph(
    path: String,
    tint: Color,
    size: Dp = 22.dp,
) {
    Canvas(Modifier.size(size)) { drawIcon(path, tint) }
}

